template.inlineTemplate:
//PTFQRY   EXEC PGM=GIMSMP,REGION=0M
//SMPCSI   DD DISP=SHR,DSN=${instance-CSI_DATASET}
//SMPCNTL  DD *
  SET BDY(${instance-TARGET_ZONE}) .
  QUERY SYSMODS
    TYPE(PTF)
    APPLYCHECK
    FORFMID(${instance-FMID_FILTER}) .
/*
//SYSPRINT DD SYSOUT=*
//SMPOUT   DD SYSOUT=*
//SMPSNAP  DD SYSOUT=*
//SMPLIST  DD SYSOUT=*
//SMPLOG   DD DUMMY

//MFIXRPT  EXEC PGM=GIMSMP,REGION=0M
//SMPCSI   DD DISP=SHR,DSN=${instance-CSI_DATASET}
//SMPCNTL  DD *
  SET BDY(GLOBAL) .
  REPORT MISSINGFIX ZONES(${instance-TARGET_ZONE})
    FIXCAT(IBM.TargetSystem-RequiredService.z/OS.V2R5,
           IBM.DrivingSystem-RequiredService) .
/*
//SYSPRINT DD SYSOUT=*
//SMPOUT   DD SYSOUT=*
//SMPSNAP  DD SYSOUT=*
//SMPLIST  DD SYSOUT=*
//SMPLOG   DD DUMMY

//HOLDQRY  EXEC PGM=GIMSMP,REGION=0M
//SMPCSI   DD DISP=SHR,DSN=${instance-CSI_DATASET}
//SMPCNTL  DD *
  SET BDY(${instance-TARGET_ZONE}) .
  QUERY SYSMODS
    TYPE(PTF)
    HOLD .
/*
//SYSPRINT DD SYSOUT=*
//SMPOUT   DD SYSOUT=*
//SMPSNAP  DD SYSOUT=*
//SMPLIST  DD SYSOUT=*
//SMPLOG   DD DUMMY

//ERRQRY   EXEC PGM=GIMSMP,REGION=0M
//SMPCSI   DD DISP=SHR,DSN=${instance-CSI_DATASET}
//SMPCNTL  DD *
  SET BDY(${instance-TARGET_ZONE}) .
  QUERY SYSMODS
    TYPE(PTF)
    STATUS(ERROR) .
/*
//SYSPRINT DD SYSOUT=*
//SMPOUT   DD SYSOUT=*
//SMPSNAP  DD SYSOUT=*
//SMPLIST  DD SYSOUT=*
//SMPLOG   DD DUMMY
